import io
import json
import os
from unittest.mock import patch
import openai_client

class Response(io.BytesIO):
    pass

result = {\"output\": [{\"type\": \"reasoning\", \"content\": []}, {\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}, {\"type\": \"output_text\", \"text\": \" world\"}]}]}

def mock_urlopen(request, timeout):
    assert request.full_url == \"https://api.openai.com/v1/responses\"
    assert request.get_header(\"Authorization\") == \"Bearer test-key\"
    assert json.loads(request.data) == {\"model\": \"gpt-4.1-mini\", \"input\": \"private test\", \"store\": False}
    assert timeout == 30
    return Response(json.dumps(result).encode())

with patch.dict(os.environ, {\"OPENAI_API_KEY\": \"test-key\"}), patch.object(openai_client, \"urlopen\", mock_urlopen):
    assert openai_client.send_prompt(\"private test\") == \"hello world\"
try:
    openai_client.send_prompt(\"\")
except ValueError:
    pass
else:
    raise AssertionError(\"blank prompt must fail\")
print(\"mocked request and response checks passed\")
